const setValue = (obj, [path, ...rest], val) => {
  if (rest.length === 0) {
    return Object.assign({}, obj, { [path]: val });
  } else {
    return Object.assign({}, obj, {
      [path]: setValue(obj[path] || {}, rest, val),
    });
  }
};

const getValue = (obj, [path, ...rest], val) => {
  if (rest.length === 0) {
    return obj[path] || val;
  } else {
    return obj[path] ? getValue(obj[path], rest, val) : val;
  }
};

