function math_prime_factors(n) {
    const result = {}

    for(let i = 2; i * i <= n; i++) {
        if(n % i === 0) {
            n /= i
            result[i] = 1

            while(n % i === 0) {
                n /= i
                result[i]++
            }
        }
    }

