  var s = next();
  var isA = false;
  var isB = false;
  for(var i = 0; i < s.length; i++){
    if(s[i] == "A"){
      isA = true;
    }
    if(s[i] == "B"){
      isB = true;
    }
  }
  if(isA && isB){
    myout("Yes");
  }else{
    myout("No");
  }
}

